"""Builds session_host.c from carplaytest.c: the /info, SETUP and screen-stream code
with stubs, so session_check.py can test it on the Mac. Run before compiling session_host."""
src = open('../carplaytest.c').read()
def grab(start, end):
    s = src.index(start); return src[s:src.index(end, s)]
HDR = '/* generated by session_extract (test only): pieces of carplaytest.c with stubs */\n#include <stdio.h>\n#include <string.h>\n#include <stdint.h>\n#include "../pair.h"\n#include "../bplist.h"\n#include "../third_party/monocypher/monocypher.h"\n#include "../third_party/monocypher/monocypher-ed25519.h"\n#define ACC_NAME "Head Unit"\n#define EVENT_PORT 7001\n#define SCREEN_PORT 7002\n#define TIMING_PORT 7010\n#define KEEPALIVE_PORT 7011\nstatic pair_ctx pc;\nstatic uint32_t ms_now; static uint32_t millis(void) { return ms_now += 5; }\nstatic char *str_cat(char *p, const char *s) { while (*s) *p++ = *s++; *p = 0; return p; }\nstatic char *str_u(char *p, unsigned v) { char t[12]; int n = 0; do { t[n++] = (char)(\'0\' + v % 10); v /= 10; } while (v); while (n) *p++ = t[--n]; *p = 0; return p; }\nstatic char logbuf[256]; static void log_tag(const char *t) { strcat(logbuf, t); strcat(logbuf, " "); }\nstatic void mmove(uint8_t *d, const uint8_t *s, int n) { memmove(d, s, (size_t)n); }\nstatic void ctr_nonce(uint8_t n[12], uint64_t c) { for (int i = 0; i < 4; i++) n[i] = 0; for (int i = 0; i < 8; i++) n[4 + i] = (uint8_t)(c >> (8 * i)); }\nstatic void hk(uint8_t out[32], const char *salt, const char *info)\n{ crypto_sha512_hkdf(out, 32, pc.pv_shared, 32, (const uint8_t *)salt, strlen(salt), (const uint8_t *)info, strlen(info)); }\n'
TAIL = '\nstatic int unhex(uint8_t *o, const char *s) { int n = 0; while (s[0] > \' \' && s[1] > \' \') { sscanf(s, "%2hhx", &o[n++]); s += 2; } return n; }\nint main(void)\n{\n\tstatic char cmd[4], d[3000000]; static uint8_t in[1500000], out[65536];\n\tfor (int i = 0; i < 32; i++) pc.pv_shared[i] = (uint8_t)(i * 3 + 7);\n\twhile (scanf("%3s", cmd) == 1) {\n\t\tif (cmd[0] == \'I\') { int n = info_plist(out, sizeof out); for (int i = 0; i < n; i++) printf("%02x", out[i]); printf("\\n"); }\n\t\telse if (cmd[0] == \'S\') { scanf("%2999999s", d); int n = unhex(in, d); int r = setup_reply(in, n, out, sizeof out);\n\t\t\tfor (int i = 0; i < r; i++) printf("%02x", out[i]); printf(" "); for (int i = 0; i < 32; i++) printf("%02x", scr_key[i]); printf(" %s\\n", logbuf); }\n\t\telse if (cmd[0] == \'V\') { scanf("%2999999s", d); int n = unhex(in, d);\n\t\t\tfor (int o = 0; o < n; o += 777) screen_input(in + o, n - o < 777 ? n - o : 777);   /* arrive in TCP-sized pieces */\n\t\t\tprintf("cfg %u prof %d L%d %dx%d frames %u idr %u bytes %u bad %u\\n", v_cfg, v_profile, v_level, v_w, v_h, v_frames, v_idr, v_bytes, v_bad); }\n\t\tfflush(stdout);\n\t}\n\treturn 0;\n}\n'
open('session_host.c', 'w').write(HDR + grab('#define DISPLAY_UUID', 'static int hdr_is(') + '\n'
    + grab('/* ---- the screen stream: 128-byte header', 'static void on_tcp(') + TAIL)
